"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def _read_file(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read().splitlines()


def _read_include(path):
    try:
        return _read_file(path)
    except FileNotFoundError:
        raise ConfigError("included file not found: {}".format(path))
    except OSError as exc:
        raise ConfigError("cannot read included file {}: {}".format(path, exc))


def _expand(path, lines, stack):
    """Return ``lines`` with ``@include`` directives recursively expanded.

    ``stack`` holds the real paths of the files currently being expanded and
    is used to detect include cycles.
    """
    base_dir = os.path.dirname(os.path.abspath(path))
    expanded = []
    for lineno, raw in enumerate(lines, start=1):
        parts = raw.split(None, 1)
        if not parts or parts[0] != INCLUDE_DIRECTIVE:
            expanded.append(raw)
            continue
        target = parts[1].strip() if len(parts) > 1 else ""
        if not target:
            raise ConfigError("{}:{}: @include requires a path".format(path, lineno))
        target = os.path.join(base_dir, target)
        real_target = os.path.realpath(target)
        if real_target in stack:
            chain = " -> ".join(stack + [real_target])
            raise ConfigError("include cycle detected: {}".format(chain))
        expanded.extend(
            _expand(target, _read_include(target), stack + [real_target])
        )
    return expanded


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced in place by the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    lines = _read_file(path)
    return parse_lines(_expand(path, lines, [os.path.realpath(path)]))


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
